import React, {forwardRef, useCallback, useMemo} from 'react';

import type {SelectOption} from '@gravity-ui/uikit';

import type {MultiAutocompleteProps} from './MultiAutocomplete';
import {MultiAutocomplete} from './MultiAutocomplete';

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- It's currently used everywhere without a generic
export type AutocompleteProps<TValue = any> = Omit<
    MultiAutocompleteProps,
    'multiple' | 'value' | 'onUpdate'
> & {
    value?: SelectOption<TValue>;
    onUpdate: (value: SelectOption<TValue>) => void;
};

export const Autocomplete = forwardRef<HTMLButtonElement, AutocompleteProps>(
    ({value, onUpdate, ...props}, ref) => {
        const normalizedValue = useMemo(() => (value ? [value] : []), [value]);

        const handleUpdate = useCallback(
            (values: SelectOption[]) => {
                onUpdate(values[0]!);
            },
            [onUpdate],
        );

        return (
            <MultiAutocomplete
                {...props}
                ref={ref}
                value={normalizedValue}
                onUpdate={handleUpdate}
                multiple={false}
            />
        );
    },
);

Autocomplete.displayName = 'Autocomplete';
